const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const brooklyn = ee.Geometry.Rectangle([-74.05, 40.55, -73.83, 40.74]);
    const band = 'tropospheric_NO2_column_number_density';
    const scale = 3000; // Use a coarser scale to avoid timeouts with atmospheric data.

    // Define the function to get mean NO2 for a given year
    const getMeanNO2 = function(year) {
        const startDate = ee.Date.fromYMD(year, 10, 1);
        const endDate = ee.Date.fromYMD(year, 10, 23);

        const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
            .filterBounds(brooklyn)
            .filterDate(startDate, endDate)
            .select([band, 'qa_value']);

        // Check for empty collection
        const size = collection.size().getInfo();
        if (size === 0) {
            return { 'value': null, 'count': 0, 'size': size, 'year': year };
        }

        // Apply quality assurance mask (recommended for S5P is > 0.75)
        const maskedCollection = collection.map(function(image) {
            const qaMask = image.select('qa_value').gt(0.75);
            return image.select(band).updateMask(qaMask);
        });

        const meanImage = maskedCollection.mean();

        const stats = meanImage.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: brooklyn,
            scale: scale,
            maxPixels: 1e9
        });

        return {
            'value': stats.get(band).getInfo(),
            'count': stats.get('count').getInfo(),
            'size': size,
            'year': year
        };
    };

    // 2. Data Acquisition & Processing for each period
    const data2021 = getMeanNO2(2021);
    const data2019 = getMeanNO2(2019);
    const data2018 = getMeanNO2(2018);

    // 3. Validation & Final Answer
    if (data2021.size === 0 || data2019.size === 0 || data2018.size === 0) {
        console.log(`Image Collection Size - 2021: ${data2021.size}, 2019: ${data2019.size}, 2018: ${data2018.size}`);
        console.log("Empty image collection for one or more periods.");
        console.log("A");
        return;
    }

    if (data2021.count === 0 || data2019.count === 0 || data2018.count === 0) {
        console.log(`Valid Pixel Count - 2021: ${data2021.count}, 2019: ${data2019.count}, 2018: ${data2018.count}`);
        console.log("No valid pixels found after QA masking for one or more periods.");
        console.log("C2");
        return;
    }

    if (data2021.value === null || data2019.value === null || data2018.value === null) {
        console.log("Calculation failed, received null value for mean NO2.");
        console.log("C3");
        return;
    }

    const mean2018_2019 = (data2018.value + data2019.value) / 2;

    console.log(`2021 Mean NO2 (mol/m^2): ${data2021.value.toExponential(4)}`);
    console.log(`2019 Mean NO2 (mol/m^2): ${data2019.value.toExponential(4)}`);
    console.log(`2018 Mean NO2 (mol/m^2): ${data2018.value.toExponential(4)}`);
    console.log(`2018-2019 Combined Mean (mol/m^2): ${mean2018_2019.toExponential(4)}`);

    if (data2021.value < mean2018_2019) {
        console.log("2021 concentration was lower than the 2018-2019 average.");
        console.log("A");
    } else {
        console.log("2021 concentration was not lower than the 2018-2019 average.");
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
